 x=t.randn((b,2048),generator=g).bfloat16();w=(t.randn((128,2048),generator=g)/math.sqrt(2048)).bfloat16();xg=x.cuda();recipe=dict(kind='tile_pages',layout='xcore_mma',tile_n=tn,tile_k=32,source=dict(kind='alias',source='matrix'));packed=_packed_gpu(recipe,lambda key:w).cuda();logits=t.full((b,128),-93,device='cuda',dtype=t.bfloat16);tiles=128//tn;slots=(104+tiles-1)//tiles+1;partials=t.zeros((tiles,slots,b,tn+1),device='cuda',dtype=t.float32);tickets=t.zeros(tiles,device='cuda',dtype=t.int32);route_ticket=t.zeros(1,device='cuda',dtype=t.int32)
